/**
 * i18n.ts: every user-facing string, in English and Bahasa Indonesia.
 *
 * Rules (CLAUDE.md): both languages always; Indonesian reads as everyday
 * Indonesian ("Akun" for account); no em dash anywhere; a missing value prints
 * "-". Web pages get both languages as a static bundle
 * (public/app/static/js/i18n-all.js, generated by scripts/build_i18n.ts);
 * Telegram and server-rendered reports call t() here.
 *
 * Error keys are `err.<code>`, one per code an action or the engine can
 * return. tests/unit/i18n.test.ts fails when a code has no string.
 */

export const DEFAULT_LANG = "en";
export const SUPPORTED_LANGS = ["en", "id"] as const;
export type Lang = (typeof SUPPORTED_LANGS)[number];

export function normalizeLang(lang: string | null | undefined): Lang {
  const code = String(lang ?? "").trim().toLowerCase().slice(0, 2);
  return code === "id" ? "id" : "en";
}

interface Entry {
  en: string;
  id: string;
}

