/** Translate, with {name} placeholders filled from `params`. */
export function t(key: string, lang: string = DEFAULT_LANG, params: Record<string, string | number> = {}): string {
  const e = STRINGS[key];
  let s = e ? e[normalizeLang(lang)] || e.en : key;
  for (const [k, v] of Object.entries(params)) s = s.split(`{${k}}`).join(String(v));
  return s;
}

/** Positional {0}/{1} form, matching the browser's t(key, a, b). */
export function tf(key: string, lang: string, ...subs: (string | number)[]): string {
  let s = t(key, lang);
  subs.forEach((v, i) => (s = s.split(`{${i}}`).join(String(v))));
  return s;
}

/** Both languages, flattened, for the static browser bundle. */
export function allBundles(): Record<Lang, Record<string, string>> {
  const en: Record<string, string> = {};
  const id: Record<string, string> = {};
  for (const [k, v] of Object.entries(STRINGS)) {
    en[k] = v.en;
    id[k] = v.id;
  }
  return { en, id };
}
